// aim.cpp
// VALORANT aim assist: world-to-screen projection, entity head tracking,
// smoothed crosshair delta within a 240px cone.
//
// Build (smoke test):
//   cl /std:c++17 /O2 /W3 /DSMOKE_TEST aim.cpp /Fe:aim_test.exe
//
// Exported helpers (all return false / zero-vector on failure):
//   bool  WorldToScreen(const Vec3& world, const ViewMatrix& vm,
//                       int sw, int sh, Vec2& out)
//   Vec2  GetHeadDelta(const Vec3& headWorld, const ViewMatrix& vm,
//                      int sw, int sh, float smoothFactor)
//   bool  FindBestTarget(const EntityList& list, const ViewMatrix& vm,
//                        int sw, int sh, float conePx,
//                        float smoothFactor, Vec2& outDelta)

#include <cmath>
#include <cstdint>
#include <cstring>
#include <limits>
#include <array>

// ---------------------------------------------------------------------------
// Math primitives
// ---------------------------------------------------------------------------

struct Vec2 {
    float x = 0.f, y = 0.f;
    Vec2 operator+(const Vec2& o) const { return {x + o.x, y + o.y}; }
    Vec2 operator-(const Vec2& o) const { return {x - o.x, y - o.y}; }
    Vec2 operator*(float s)       const { return {x * s,   y * s};   }
    float length() const { return std::sqrtf(x * x + y * y); }
};

struct Vec3 {
    float x = 0.f, y = 0.f, z = 0.f;
};

// Row-major 4x4 view-projection matrix (matches DirectX conventions used
// by Unreal Engine, which powers VALORANT).
struct ViewMatrix {
    float m[4][4]{};
};

// ---------------------------------------------------------------------------
// World-to-screen projection
// ---------------------------------------------------------------------------
// Returns true when the point projects inside the viewport.
// out.x and out.y are in pixels, (0,0) top-left.
bool WorldToScreen(const Vec3& world,
                   const ViewMatrix& vm,
                   int screenW, int screenH,
                   Vec2& out)
{
    // Clip-space transform: clip = VM * [wx, wy, wz, 1]^T
    // Using row-major storage: clip_i = sum_j( m[i][j] * v[j] )
    float clipX = vm.m[0][0] * world.x + vm.m[0][1] * world.y
                + vm.m[0][2] * world.z + vm.m[0][3];
    float clipY = vm.m[1][0] * world.x + vm.m[1][1] * world.y
                + vm.m[1][2] * world.z + vm.m[1][3];
    float clipW = vm.m[3][0] * world.x + vm.m[3][1] * world.y
                + vm.m[3][2] * world.z + vm.m[3][3];

    // Behind camera or at infinity
    if (clipW < 1e-4f) return false;

    float ndcX = clipX / clipW;   // [-1, +1]
    float ndcY = clipY / clipW;   // [-1, +1]

    // Viewport transform (DirectX: Y flipped)
    out.x = (1.f + ndcX) * 0.5f * static_cast<float>(screenW);
    out.y = (1.f - ndcY) * 0.5f * static_cast<float>(screenH);

    return (ndcX >= -1.f && ndcX <= 1.f &&
            ndcY >= -1.f && ndcY <= 1.f);
}

// ---------------------------------------------------------------------------
// Head delta with exponential smoothing
// ---------------------------------------------------------------------------
// smoothFactor in (0, 1]: 1.0 = no smoothing (snap), 0.05 = very smooth.
// Returns the pixel delta to move the crosshair toward the projected head.
Vec2 GetHeadDelta(const Vec3& headWorld,
                  const ViewMatrix& vm,
                  int screenW, int screenH,
                  float smoothFactor)
{
    Vec2 headScreen;
    if (!WorldToScreen(headWorld, vm, screenW, screenH, headScreen))
        return {};

    Vec2 center{ static_cast<float>(screenW) * 0.5f,
                 static_cast<float>(screenH) * 0.5f };

    Vec2 raw = headScreen - center;

    // Clamp smoothFactor to a sane range
    if (smoothFactor <= 0.f) smoothFactor = 0.01f;
    if (smoothFactor >  1.f) smoothFactor = 1.f;

    return raw * smoothFactor;
}

// ---------------------------------------------------------------------------
// Entity list interface
// ---------------------------------------------------------------------------
// Callers fill EntityList and pass it to FindBestTarget.
// headPos is the world-space head bone position.
// visible:  true when the bone is not occluded by level geometry.

struct Entity {
    Vec3  headPos{};
    bool  visible  = false;
    bool  alive    = true;
    bool  isEnemy  = true;
};

static constexpr int kMaxEntities = 128;

struct EntityList {
    std::array<Entity, kMaxEntities> entities{};
    int count = 0;         // number of valid entries
};

// ---------------------------------------------------------------------------
// FindBestTarget
// ---------------------------------------------------------------------------
// Scans the entity list, projects every enemy head, keeps only those within
// conePx pixels of the crosshair, and returns a smoothed delta toward the
// closest one.
//
// conePx    – cone radius in screen pixels (spec: 240 px)
// outDelta  – pixel delta to apply to raw mouse input (multiply by sens)
//
// Returns true when a target was found inside the cone.
bool FindBestTarget(const EntityList& list,
                    const ViewMatrix&  vm,
                    int   screenW,
                    int   screenH,
                    float conePx,
                    float smoothFactor,
                    Vec2& outDelta)
{
    const Vec2 center{ static_cast<float>(screenW) * 0.5f,
                       static_cast<float>(screenH) * 0.5f };

    float bestDist  = std::numeric_limits<float>::max();
    Vec2  bestDelta{};
    bool  found     = false;

    for (int i = 0; i < list.count && i < kMaxEntities; ++i) {
        const Entity& ent = list.entities[i];
        if (!ent.alive || !ent.isEnemy || !ent.visible) continue;

        Vec2 headScreen;
        if (!WorldToScreen(ent.headPos, vm, screenW, screenH, headScreen))
            continue;

        Vec2  delta = headScreen - center;
        float dist  = delta.length();

        if (dist > conePx) continue;   // outside the 240 px cone

        if (dist < bestDist) {
            bestDist  = dist;
            bestDelta = delta;
            found     = true;
        }
    }

    if (!found) {
        outDelta = {};
        return false;
    }

    // Apply exponential smoothing to the raw delta
    if (smoothFactor <= 0.f) smoothFactor = 0.01f;
    if (smoothFactor >  1.f) smoothFactor = 1.f;

    outDelta = bestDelta * smoothFactor;
    return true;
}

// ---------------------------------------------------------------------------
// Smoke-test entry point
// ---------------------------------------------------------------------------
#ifdef SMOKE_TEST
#include <cstdio>

int main()
{
    // Construct a trivial identity-like view matrix where
    // world XY maps directly to screen NDC XY.
    ViewMatrix vm{};
    vm.m[0][0] = 1.f;   // X passthrough
    vm.m[1][1] = 1.f;   // Y passthrough
    vm.m[2][2] = 1.f;
    vm.m[3][3] = 1.f;

    constexpr int W = 1920, H = 1080;

    // A head exactly at the view origin should project to screen centre.
    Vec3 head{ 0.f, 0.f, 0.f };
    Vec2 screen;
    bool ok = WorldToScreen(head, vm, W, H, screen);
    std::printf("WorldToScreen origin: ok=%d  screen=(%.1f,%.1f)  expected=(%.1f,%.1f)\n",
                (int)ok, screen.x, screen.y, W * 0.5f, H * 0.5f);

    // Delta at centre should be (0,0).
    Vec2 delta = GetHeadDelta(head, vm, W, H, 1.0f);
    std::printf("HeadDelta at centre: (%.3f, %.3f)  expected (0.000, 0.000)\n",
                delta.x, delta.y);

    // A head 100 px right of centre in NDC:
    // NDC X = 100 / (W/2) = 100/960 ≈ 0.1042
    Vec3 head2{ 100.f / (W * 0.5f), 0.f, 0.f };
    Vec2 delta2 = GetHeadDelta(head2, vm, W, H, 0.5f);
    std::printf("HeadDelta 100px right, smooth=0.5: (%.3f, %.3f)  expected (~50, ~0)\n",
                delta2.x, delta2.y);

    // FindBestTarget: one visible enemy inside 240 px cone
    EntityList list{};
    list.count              = 1;
    list.entities[0].headPos = head2;
    list.entities[0].visible = true;
    list.entities[0].alive   = true;
    list.entities[0].isEnemy = true;

    Vec2 outDelta;
    bool hit = FindBestTarget(list, vm, W, H, 240.f, 0.5f, outDelta);
    std::printf("FindBestTarget in cone: found=%d  delta=(%.3f, %.3f)\n",
                (int)hit, outDelta.x, outDelta.y);

    // Enemy outside cone: dist ≈ 300 px
    list.entities[0].headPos = Vec3{ 300.f / (W * 0.5f), 0.f, 0.f };
    bool miss = FindBestTarget(list, vm, W, H, 240.f, 0.5f, outDelta);
    std::printf("FindBestTarget outside cone: found=%d  (expected 0)\n", (int)miss);

    return 0;
}
#endif // SMOKE_TEST
